  var SALES = [
    { level: 2, q: 'Before pitching anything, a consultative salesperson\u2019s first move should be to\u2026', a: 'Ask questions to uncover the prospect\u2019s actual pain point', d: ['Ask questions to uncover the prospect\u2019s actual pain point', 'List every feature of the product', 'Offer the biggest possible discount', 'Talk as much as possible to fill silence'], why: 'Needs-based (consultative) selling starts by understanding the specific problem \u2014 pitching before that means guessing what matters to the buyer.' },
    { level: 5, q: 'What is the main advantage of an open question ("What\u2019s making this hard right now?") over a closed one ("Is this hard?") early in a sales conversation?', a: 'It gets the prospect talking and reveals real motivations, not just a yes/no', d: ['It gets the prospect talking and reveals real motivations, not just a yes/no', 'It is quicker to answer', 'It sounds more formal', 'It avoids the prospect thinking at all'], why: 'Open questions surface the reasoning and emotion behind a decision \u2014 closed questions only confirm or deny a single guess.' },
    { level: 8, q: '"When would you like to get started, this week or next?" is an example of\u2026', a: 'A presupposition (assumptive) question', d: ['A presupposition (assumptive) question', 'A closed yes/no question', 'An objection-handling phrase', 'A discovery question'], why: 'This question grammatically assumes the sale is already happening, skipping past "whether" straight to "when" or "which" \u2014 a classic framing technique.' },
    { level: 11, q: 'Offering "Tuesday or Thursday?" instead of "Do you want to book a call?" is called\u2026', a: 'An either/or (alternative) close', d: ['An either/or (alternative) close', 'The door-in-the-face technique', 'Loss framing', 'A discovery question'], why: 'Both options move toward a yes \u2014 it removes the easy binary "no" by replacing it with a choice between two positive outcomes.' },
    { level: 14, q: 'Why do skilled salespeople say "investment" instead of "cost" or "price"?', a: 'It reframes the same number as something that returns value, not just an expense', d: ['It reframes the same number as something that returns value, not just an expense', 'It is required by consumer protection law', 'It makes the number sound smaller mathematically', 'It has no real effect on perception'], why: 'This is a framing effect: identical numbers feel different depending on whether they\u2019re labelled a loss (cost) or a value-generating action (investment).' },
    { level: 17, q: '"What is the current situation actually costing you \u2014 in time, money or stress?" is a\u2026', a: 'Pain-focused (cost-of-inaction) question', d: ['Pain-focused (cost-of-inaction) question', 'Closing question', 'Feature-focused question', 'Rapport-building question'], why: 'Making the cost of NOT changing explicit and specific increases motivation to act, tapping into loss aversion.' },
    { level: 20, q: 'Which builds more perceived authority: "I\u2019ve helped a lot of people with this" or "I\u2019ve helped 47 businesses fix this exact problem in the last year"?', a: '"I\u2019ve helped 47 businesses fix this exact problem in the last year"', d: ['"I\u2019ve helped 47 businesses fix this exact problem in the last year"', '"I\u2019ve helped a lot of people with this"', 'Neither \u2014 vague and specific claims land equally', 'It depends only on tone of voice, never wording'], why: 'Specific numbers and details read as more credible and verifiable than vague claims \u2014 this is a well-documented persuasion effect (the "specificity" or "concreteness" effect).' },
    { level: 23, q: 'Leading a pitch with a specific client result ("We took X from \u00a310k to \u00a340k a month") before explaining the method is an example of\u2026', a: 'Results-first framing, using social proof to establish authority up front', d: ['Results-first framing, using social proof to establish authority up front', 'The sunk cost fallacy', 'A closed question', 'Reciprocity'], why: 'Opening with proof of outcome (not process) establishes credibility before you\u2019ve asked for anything, borrowing Cialdini\u2019s social proof and authority principles together.' },
    { level: 26, q: 'What is the "feel, felt, found" framework used for?', a: 'Handling objections empathetically before presenting reassuring evidence', d: ['Handling objections empathetically before presenting reassuring evidence', 'Opening a cold call', 'Closing a sale immediately', 'Setting a price anchor'], why: '"I understand how you feel \u2014 other clients felt the same \u2014 here\u2019s what they found" validates the objection before reframing it, rather than arguing against it directly.' },
    { level: 29, q: '"Imagine six months from now, once this is finally sorted\u2026" is an example of\u2026', a: 'Future pacing', d: ['Future pacing', 'The door-in-the-face technique', 'A closed question', 'Loss aversion framing'], why: 'Future pacing gets the prospect vividly imagining the positive outcome as already real, which increases desire and reduces perceived risk of committing.' },
    { level: 32, q: 'Which phrasing projects more authority: "I think this might maybe help" or "Here\u2019s what I recommend, and here\u2019s why"?', a: '"Here\u2019s what I recommend, and here\u2019s why"', d: ['"Here\u2019s what I recommend, and here\u2019s why"', '"I think this might maybe help"', 'They project identical authority', 'Hedging language always sounds more trustworthy'], why: 'Hedging language ("might", "maybe", "I guess") undercuts perceived expertise \u2014 confident, direct recommendation backed by a reason signals authority.' },
    { level: 35, q: 'An assumptive close ("I\u2019ll get the paperwork started") works by\u2026', a: 'Treating the decision as already made and moving to the next practical step', d: ['Treating the decision as already made and moving to the next practical step', 'Explicitly asking permission before every step', 'Highlighting scarcity', 'Reducing the price'], why: 'This mirrors the presupposition question technique \u2014 momentum and consistency pressure build when the conversation proceeds as if "yes" already happened.' },
    { level: 38, q: 'Showing the premium package first, then the mid-tier package, uses which effect to make the mid-tier look reasonably priced?', a: 'Anchoring', d: ['Anchoring', 'Reciprocity', 'The bystander effect', 'Cognitive dissonance'], why: 'The first (highest) price seen becomes the mental reference point, making the next option look comparatively affordable by contrast.' },
    { level: 41, q: 'What is the key ethical line between using scarcity/urgency in sales and manipulating someone with it?', a: 'Whether the scarcity or deadline is genuinely true, not fabricated to pressure a decision', d: ['Whether the scarcity or deadline is genuinely true, not fabricated to pressure a decision', 'Scarcity is always manipulative, with no ethical use', 'Urgency is only ethical in B2B sales, never consumer sales', 'There is no meaningful ethical distinction'], why: 'Real limited availability or a real deadline respects the buyer\u2019s ability to make an informed choice \u2014 a fake countdown timer does not, even though both use the same psychological lever.' },
    { level: 44, q: 'Being featured in a well-known publication or endorsed by a recognised expert builds authority mainly through\u2026', a: 'Third-party validation (borrowed credibility)', d: ['Third-party validation (borrowed credibility)', 'The sunk cost fallacy', 'A closed question', 'The bystander effect'], why: 'Credibility transfers from an already-trusted source to you \u2014 this is why "as featured in\u2026" and expert endorsements are used so heavily in positioning.' },
    { level: 47, q: 'A "trial close" (e.g. "How does this sound so far?") mid-conversation is used to\u2026', a: 'Gauge buying interest before investing more time in the pitch', d: ['Gauge buying interest before investing more time in the pitch', 'End the conversation immediately', 'Introduce a new objection', 'Lower the price'], why: 'Trial closes test the temperature of the conversation early, letting a salesperson adjust course rather than pitching blind for twenty minutes.' },
    { level: 50, q: 'Responding to an objection with "That\u2019s a great question \u2014 let me explain" is a technique for\u2026', a: 'Reframing an objection as a normal, welcome part of the conversation rather than a conflict', d: ['Reframing an objection as a normal, welcome part of the conversation rather than a conflict', 'Ending the sale immediately', 'Avoiding answering the objection', 'Increasing the price'], why: 'This defuses defensiveness on both sides and buys a moment to respond thoughtfully, instead of the objection feeling like an attack to counter.' },
    { level: 53, q: 'After stating a price, an experienced negotiator often deliberately\u2026', a: 'Stays silent and lets the other person respond first', d: ['Stays silent and lets the other person respond first', 'Immediately offers a discount', 'Repeats the price three times', 'Changes the subject'], why: 'Silence after a price creates social pressure for the other person to fill it \u2014 jumping in first (e.g. with an unprompted discount) gives away negotiating power for free.' },
    { level: 56, q: 'Positioning yourself as a "guide" who helps the client become the hero of their own story, rather than positioning yourself as the hero, tends to\u2026', a: 'Build more trust and authority, since it centres the client\u2019s outcome, not the seller\u2019s ego', d: ['Build more trust and authority, since it centres the client\u2019s outcome, not the seller\u2019s ego', 'Always come across as weak or unconfident', 'Have no effect on how a pitch is received', 'Only work in written marketing, never in conversation'], why: 'This "guide, not hero" framing (popularised in StoryBrand-style messaging) signals expertise through service and results, rather than through self-promotion \u2014 read as more authoritative, not less.' },
    { level: 60, q: 'A prospect says: "I need to think about it." A salesperson replies: "Totally understand \u2014 usually when someone says that, it\u2019s really about one of two or three things. Is it the timing, the price, or something else?" What is this response combining?', a: 'Objection reframing (feel/felt/found style) with an either/or narrowing question to surface the real objection', d: ['Objection reframing (feel/felt/found style) with an either/or narrowing question to surface the real objection', 'A pure closed yes/no question with no framing', 'A price anchor with no question at all', 'A future-pacing statement only'], why: 'This combines validating the stall (normalising it, not arguing) with a structured either/or question that narrows a vague objection into something specific and addressable \u2014 several techniques working together.' }
  ];

  // Dark Psychology — manipulation tactics, coercive control and high-control-group ("cult")
  // methods. Framed throughout for RECOGNITION and DEFENCE, not for performing these tactics
  // on others — every "why" explains how to spot and disengage from the pattern. Deliberately
  // kept OUT of POOL_KEYS/LEVEL_BANDS/QT_TYPES below, so it never appears in the mixed ladder,
  // Quick Test, Placement Test or Daily Challenge — it's opt-in only, behind an 18+ gate in the
  // app UI, reachable solely via its own topic card.
  var DARK = [
    { level: 4, q: 'The "Dark Triad" in personality psychology refers to which cluster of traits, all linked to manipulative and exploitative behaviour?', a: 'Narcissism, Machiavellianism and psychopathy', d: ['Narcissism, Machiavellianism and psychopathy', 'Anxiety, depression and anger', 'Optimism, extraversion and openness', 'Authority, scarcity and reciprocity'], why: 'Coined by Paulhus and Williams (2002), these three overlapping traits — grandiosity, cynical manipulation, and low empathy/impulsivity — predict exploitative behaviour more reliably than any one trait alone.' },
    { level: 9, q: 'Repeatedly telling someone their memory or perception of events is wrong, until they doubt their own judgement, is called…', a: 'Gaslighting', d: ['Gaslighting', 'Negging', 'Triangulation', 'Love bombing'], why: 'Named after the 1944 film "Gaslight," this tactic erodes a target’s trust in their own perception, making them more dependent on the manipulator’s version of events. Recognising the pattern — not "was I wrong?" but "why do they keep denying things I clearly remember?" — is the first defence.' },
    { level: 14, q: 'Overwhelming a new partner with excessive affection, gifts and attention very early in a relationship is a manipulation tactic known as…', a: 'Love bombing', d: ['Love bombing', 'Gaslighting', 'Grey rocking', 'Negging'], why: 'Love bombing builds intense trust and attachment fast, which can later be exploited — it’s a recognised early warning sign in coercive-control research, not genuine affection moving at a healthy pace.' },
    { level: 19, q: 'When confronted about their own bad behaviour, someone who denies it happened, attacks the accuser’s character, then claims THEY are actually the victim is using…', a: 'DARVO (Deny, Attack, Reverse Victim and Offender)', d: ['DARVO (Deny, Attack, Reverse Victim and Offender)', 'Gaslighting', 'Triangulation', 'The sunk cost fallacy'], why: 'A term from psychologist Jennifer Freyd’s research, DARVO is a well-documented pattern for deflecting accountability by flipping who appears to be harming whom — naming it out loud, even just to yourself, breaks its effect.' },
    { level: 24, q: 'A pattern of unpredictable warmth and coldness that makes a target work harder to win back approval is exploiting…', a: 'Intermittent reinforcement', d: ['Intermittent reinforcement', 'Cognitive dissonance', 'The halo effect', 'Social proof'], why: 'B.F. Skinner found unpredictable, occasional rewards create the strongest, most persistent behaviour — stronger than reliable, constant reward — which is why inconsistent affection can feel so hard to walk away from.' },
    { level: 29, q: 'Deliberately bringing a third person into a two-person conflict — unfavourably comparing a partner to an ex, a coworker, or a friend — to create jealousy and insecurity, is called…', a: 'Triangulation', d: ['Triangulation', 'Gaslighting', 'Love bombing', 'Negging'], why: 'Triangulation keeps a target competing for approval, which destabilises their sense of security and makes the manipulator’s attention feel artificially scarce and valuable.' },
    { level: 33, q: 'Coercive control, as researcher Evan Stark defined it (now a criminal offence in the UK), is best described as…', a: 'An ongoing pattern that isolates, monitors, degrades and restricts a person’s freedom — not just isolated incidents', d: ['An ongoing pattern that isolates, monitors, degrades and restricts a person’s freedom — not just isolated incidents', 'A single severe act of physical violence', 'Any disagreement within a relationship', 'A legal term with no real psychological basis'], why: 'It’s recognised as a specific offence precisely because the cumulative pattern — not any one incident — is what traps a person, often without a single dramatic moment an outsider would immediately recognise as abuse.' },
    { level: 38, q: 'Sociologist Robert Lifton identified criteria for the "thought reform" used by cults and high-control groups. Which of these is one of them?', a: 'Milieu control — restricting a member’s access to outside information and relationships', d: ['Milieu control — restricting a member’s access to outside information and relationships', 'Encouraging independent, critical thinking', 'Unrestricted contact with family and friends', 'Fully transparent, publicly audited finances'], why: 'Lifton’s eight criteria, from his 1961 study of Chinese thought-reform camps, still underpin how modern researchers identify high-control groups — cutting off outside information and relationships is one of the most consistent, load-bearing tactics.' },
    { level: 43, q: 'A recommended way to disengage from someone who feeds on emotional reaction, without escalating a confrontation, is often called…', a: 'Grey rocking — becoming deliberately unresponsive and uninteresting to engage with', d: ['Grey rocking — becoming deliberately unresponsive and uninteresting to engage with', 'Love bombing them back', 'Public confrontation', 'Triangulating with a mutual friend'], why: 'Grey rocking removes the emotional reaction a manipulator is seeking, making the target a less rewarding target over time — it’s a defensive tactic for disengaging, not a way to "win" an argument.' },
    { level: 48, q: 'A backhanded compliment designed to lower someone’s self-esteem just enough to make them seek the giver’s approval is called…', a: 'Negging', d: ['Negging', 'Gaslighting', 'Anchoring', 'Framing'], why: 'Popularised by pickup-artist culture, negging exploits the same approval-seeking psychology used more broadly in coercive relationships — simply recognising it tends to defuse its effect almost immediately.' },
    { level: 53, q: 'Edward Bernays, often called the "father of public relations," argued mass opinion is shaped best by…', a: 'Appealing to unconscious emotional associations and group identity, not logical argument', d: ['Appealing to unconscious emotional associations and group identity, not logical argument', 'Only using verifiable statistics', 'Direct, explicit threats', 'Random, unstructured messaging'], why: 'Bernays pioneered applying psychological principles to mass persuasion in the 1920s — the same emotional-association techniques are visible today in advertising, political messaging and cult recruitment, which is why recognising them is a genuinely useful defensive skill.' },
    { level: 6, q: 'Pressuring, guilt-tripping or repeatedly wearing someone down into sex they don’t actually want — with no physical force involved — is still…', a: 'Sexual coercion', d: ['Sexual coercion', 'A normal part of negotiation in relationships', 'Only a problem if physical force is used', 'Flirting'], why: 'Sexual coercion doesn’t require force to be real — sulking, repeated pressure, guilt ("you’d do it if you loved me"), or wearing someone down until they give in to end the pressure all override genuine choice. This affects men and women, in any kind of relationship.' },
    { level: 16, q: 'A partner who hides, damages, or refuses to let someone use contraception, or pressures them about becoming or not becoming pregnant, is engaging in…', a: 'Reproductive coercion', d: ['Reproductive coercion', 'Family planning', 'Financial abuse', 'Gaslighting'], why: 'Reproductive coercion is a recognised, named form of coercive control — using pregnancy and contraception as tools of control over a partner’s body and future, regardless of the genders involved.' },
    { level: 27, q: 'What is the real standard for consent, according to modern consent education (not just "the absence of a no")?', a: 'Freely given, enthusiastic, and able to be withdrawn at any point', d: ['Freely given, enthusiastic, and able to be withdrawn at any point', 'Silence or not physically resisting', 'Agreeing once, which then applies to every future time', 'Whatever avoids an argument in the moment'], why: 'Consent given under pressure, guilt, fear, or exhaustion isn’t the same as a free "yes" — and consent to one act, or on one occasion, doesn’t carry forward automatically. This standard applies the same way regardless of gender or relationship history.' },
    { level: 36, q: 'A manipulator gradually pushes past a small boundary, then a slightly bigger one, checking each time whether the other person objects — this is best understood as…', a: 'Boundary testing / consent erosion, a common early tactic in coercive relationships', d: ['Boundary testing / consent erosion, a common early tactic in coercive relationships', 'Healthy relationship progression', 'Irrelevant unless a boundary is crossed all at once', 'Only something one gender does to the other'], why: 'Testing small boundaries first, then escalating once no resistance appears, is a well-documented pattern — it works precisely because each individual step looks minor, making the overall pattern hard to notice from the inside.' },
    { level: 46, q: 'Withholding affection, intimacy or sex specifically as a punishment for a partner’s unrelated behaviour (not simply not being in the mood) is…', a: 'A form of emotional/sexual control, not a neutral personal choice', d: ['A form of emotional/sexual control, not a neutral personal choice', 'Always a healthy boundary', 'Only ever done by men', 'Only ever done by women'], why: 'Genuinely not wanting intimacy at a given moment is a normal, valid boundary for anyone — the distinction is whether it’s being used strategically, as leverage tied to compliance elsewhere in the relationship. This pattern appears in relationships of every configuration, not one gender "doing it" to the other.' },
    { level: 2, q: 'Which single behaviour — like avoiding eye contact — is a scientifically reliable sign someone is lying?', a: 'None — no single cue reliably indicates deception on its own', d: ['None — no single cue reliably indicates deception on its own', 'Avoiding eye contact', 'Touching the face', 'Crossing the arms'], why: 'A major meta-analysis (Bond & DePaulo) pooling over 200 studies found people are barely better than chance (~54%) at spotting lies from isolated "tells" — the popular idea of one reliable giveaway gesture is a myth worth unlearning first.' },
    { level: 7, q: 'Before you can notice a meaningful change in someone’s behaviour, real detection training says you first need to establish…', a: 'A behavioural baseline — how the person normally acts when not under stress', d: ['A behavioural baseline — how the person normally acts when not under stress', 'Their criminal record', 'Their personality type', 'A polygraph reading'], why: 'A deviation only means something relative to a known baseline — judging someone’s behaviour against a stranger’s average, instead of their own normal pattern, is guessing, not detection.' },
    { level: 11, q: 'Interviewers sometimes ask someone to recall events in reverse order specifically to increase…', a: 'Cognitive load — since maintaining a fabricated story under that extra demand is harder than recalling a true one', d: ['Cognitive load — since maintaining a fabricated story under that extra demand is harder than recalling a true one', 'The person’s confidence', 'The interview’s length, for no functional reason', 'The person’s emotional comfort'], why: 'Lying requires inventing and tracking a false narrative, which is more mentally demanding than retrieving a real memory — genuine cognitive-interview techniques deliberately add load to make that extra effort more visible.' },
    { level: 17, q: 'Psychologist Paul Ekman’s research — later dramatised in shows like The Mentalist — found that core emotional facial expressions…', a: 'Are universal across cultures, and can flash briefly even when someone is trying to hide them', d: ['Are universal across cultures, and can flash briefly even when someone is trying to hide them', 'Are entirely learned by culture, with no universal pattern', 'Cannot be studied scientifically', 'Only appear in people who are lying'], why: 'Ekman’s Facial Action Coding System (FACS) catalogued the specific muscle movements behind genuine emotion, and found people worldwide — including isolated cultures with no exposure to Western media — produced the same expressions for the same core emotions.' },
    { level: 21, q: 'A brief, involuntary facial expression that reveals a true emotion before it’s consciously masked is called…', a: 'A micro-expression', d: ['A micro-expression', 'A macro-expression', 'A baseline deviation', 'A tell'], why: 'Micro-expressions typically last under half a second, which is why they usually require trained, deliberate attention — or slow-motion video, in research settings — to reliably catch.' },
    { level: 26, q: 'In statement analysis, someone unexplainably switching from consistent past tense to present tense mid-story ("so I walk in and he’s like…") is worth noting because…', a: 'Genuine memories are usually recalled in a consistent tense; unexplained shifts can suggest a rehearsed or reconstructed account', d: ['Genuine memories are usually recalled in a consistent tense; unexplained shifts can suggest a rehearsed or reconstructed account', 'It always proves the person is lying', 'Present tense always signals more confidence', 'Tense has no relevance to statement analysis'], why: 'This is one pattern among many used in forensic statement analysis — never proof by itself, but a genuine signal worth noticing and gently probing with a follow-up question.' },
    { level: 31, q: '"Distancing language" — avoiding direct ownership of a statement, e.g. saying "mistakes were made" instead of "I made a mistake" — is a pattern studied in…', a: 'Forensic statement analysis', d: ['Forensic statement analysis', 'Astrology', 'Graphology (handwriting analysis)', 'Palmistry'], why: 'Distancing language subtly reduces a speaker’s psychological ownership of an action, and its appearance — especially in an unprompted denial — is a genuine, studied linguistic pattern worth noticing.' },
    { level: 35, q: 'Unprompted, unnecessary qualifiers in a denial — e.g. "I did not, to the best of my recollection, take the money" — are worth noting in statement analysis because…', a: 'Truthful denials are usually direct and simple; excessive hedging can signal the speaker is protecting themselves from a later contradiction', d: ['Truthful denials are usually direct and simple; excessive hedging can signal the speaker is protecting themselves from a later contradiction', 'They always prove guilt on their own', 'Qualifiers always signal high intelligence', 'They have no meaning in statement analysis'], why: 'Like tense shifts, this is a pattern to notice and ask about, never proof by itself — real analysts always look for clusters of signals, not a single cue.' },
    { level: 40, q: 'Real behavioural profilers emphasise looking for clusters of unusual behaviour rather than single "tells" mainly because…', a: 'Any single gesture has many innocent explanations; only a consistent pattern, deviating from someone’s baseline, is meaningfully informative', d: ['Any single gesture has many innocent explanations; only a consistent pattern, deviating from someone’s baseline, is meaningfully informative', 'Clusters are just superstition with no evidence behind them', 'A single tell is always more reliable than a pattern', 'Patterns only work on strangers, never people you know'], why: 'One crossed-arm moment might just mean someone’s cold; several stress-linked behaviours changing together, right after a specific question, deviating from that person’s own baseline, is what’s actually worth attending to.' },
    { level: 44, q: 'Noticing that a normally warm, talkative colleague has become withdrawn, guarded and inconsistent over several weeks is an example of…', a: 'Tracking a genuine behavioural change over time — one of the most reliable, if slower, signals something is wrong', d: ['Tracking a genuine behavioural change over time — one of the most reliable, if slower, signals something is wrong', 'Reading a single micro-expression', 'A cold-reading technique', 'The Barnum effect'], why: 'A sudden, sustained shift in someone’s own normal pattern — mood, routine, openness — is a slower but far more trustworthy signal than trying to catch one lie in one conversation, since it’s measured against that person’s real baseline over time, not a stranger’s average.' },
    { level: 49, q: 'TV "mentalists" and cold readers appear to know things about a stranger almost instantly. What is the real skill behind this?', a: 'Extremely high-resolution observation of small details (dress, wear patterns, posture, word choice) combined with statistically common guesses', d: ['Extremely high-resolution observation of small details (dress, wear patterns, posture, word choice) combined with statistically common guesses', 'Genuine psychic ability', 'Reading minds directly', 'Pure luck, disguised through showmanship'], why: 'What looks like mind-reading is really hyper-attentive observation (a scuffed shoe, a tan line, a turn of phrase) combined with knowledge of what’s statistically likely true of most people — a practiced, learnable skill, not a supernatural gift.' },
    { level: 52, q: 'The "Barnum effect" — why vague, generic statements ("you sometimes doubt yourself, but you’re also quite resilient") feel eerily accurate to almost anyone — matters here because…', a: 'It explains why cold reading can feel convincing even with zero real information about the person', d: ['It explains why cold reading can feel convincing even with zero real information about the person', 'It proves cold readers are always genuinely psychic', 'It only affects unintelligent people', 'It has no relevance to detecting manipulation'], why: 'Recognising the Barnum effect is itself a defensive skill — it explains why horoscopes, personality tests and cold readings all feel oddly personal despite being generic enough to apply to almost anyone.' },
    { level: 56, q: 'A trained observer noticing someone’s speech pattern, breathing and posture all shift together right after one specific question — not before — is using…', a: 'Baseline deviation clustering, the strongest and most defensible real detection signal', d: ['Baseline deviation clustering, the strongest and most defensible real detection signal', 'Astrology', 'A single isolated tell', 'Random guessing'], why: 'The timing (right after a specific trigger) combined with multiple channels changing together is what separates a genuinely meaningful signal from noise — this is the real, professional-grade version of "reading" someone.' },
    { level: 58, q: 'The most important, humbling finding professional lie-detection researchers stress is…', a: 'Even trained experts (police, judges, polygraph examiners) perform only slightly better than chance without other corroborating evidence', d: ['Even trained experts (police, judges, polygraph examiners) perform only slightly better than chance without other corroborating evidence', 'Trained experts can reliably detect lies with near-100% accuracy', 'Lie detection is now a fully solved science', 'Only untrained people ever struggle with it'], why: 'Bond & DePaulo’s meta-analysis of over 200 studies found ~54% average accuracy across trained and untrained observers alike — barely above chance. The real goal of these skills is sharper attention and better follow-up questions, not becoming an infallible human polygraph.' }
  ];

  var BANKS = { persuasion: PERSUASION, biases: BIASES, habits: HABITS, emotion: EMOTION, social: SOCIAL, motivation: MOTIVATION, sales: SALES, dark: DARK };
  var TOPIC_LABELS = { persuasion: 'Persuasion & Influence', biases: 'Cognitive Biases', habits: 'Habits & Behaviour Change', emotion: 'Emotion & Decision-Making', social: 'Social Psychology', motivation: 'Motivation & Mindset', sales: 'Sales Psychology', dark: 'Dark Psychology' };
  function mcFromEntry(topicLabel, e) { return { type: 'mc', topic: topicLabel, level: e.level, prompt: e.q, options: shuffle(e.d), answer: e.a, method: e.why }; }
  function nearestByLevel(bank, level) { return bank.slice().sort(function (a, b) { return Math.abs(a.level - level) - Math.abs(b.level - level); }); }
  function generateFromBank(poolKey, level, topicLabel) { var near = nearestByLevel(BANKS[poolKey], level || 1); return mcFromEntry(topicLabel, rr(poolKey, near)); }
  function generate(topicKey, level) { return generateFromBank(topicKey, level, TOPIC_LABELS[topicKey]); }

  var POOL_KEYS = ['persuasion', 'biases', 'habits', 'emotion', 'social', 'motivation', 'sales'];
  // Sales Psychology (framing questions/phrases, authority positioning) kept in every band
  // — it spans its own full 2-60 level range, so it should show up throughout the ladder,
  // not just at one difficulty tier.
  var LEVEL_BANDS = [
    { min: 1, max: 15, pools: ['persuasion', 'habits', 'emotion', 'motivation', 'sales'] },
    { min: 16, max: 30, pools: ['habits', 'biases', 'emotion', 'social', 'sales'] },
    { min: 31, max: 45, pools: ['biases', 'social', 'motivation', 'sales'] },
    { min: 46, max: 60, pools: POOL_KEYS }
  ];
  function bandFor(level) { for (var i = 0; i < LEVEL_BANDS.length; i++) { var b = LEVEL_BANDS[i]; if (level >= b.min && level <= b.max) return b; } return LEVEL_BANDS[LEVEL_BANDS.length - 1]; }
  function generateForLevel(level) { level = Math.max(1, Math.min(60, level || 1)); return generate(pick(bandFor(level).pools), level); }
  function generateLevelSet(n, level) { var out = []; for (var i = 0; i < n; i++) out.push(generateForLevel(level)); return out; }
  function levelLabel(level) { if (level >= 50) return 'Expert'; if (level >= 40) return 'Advanced'; if (level >= 30) return 'Upper Intermediate'; if (level >= 20) return 'Intermediate'; if (level >= 10) return 'Elementary'; return 'Beginner'; }
  function gradeFromLevel(level) { if (level >= 56) return 9; if (level >= 51) return 8; if (level >= 46) return 7; if (level >= 40) return 6; if (level >= 33) return 5; if (level >= 26) return 4; if (level >= 18) return 3; if (level >= 10) return 2; return 1; }
  function generatePlacementSet(n) { n = n || 16; var out = []; for (var i = 0; i < n; i++) { var level = Math.round(1 + (i / (n - 1)) * 59); out.push(generateForLevel(level)); } return out; }
  // Dark Psychology's own dedicated test — draws only from DARK, never mixed with the main
  // pool. n defaults to the full bank so a test covers every tactic at least once.
  function generateDarkSet(n) { var levels = DARK.map(function (e) { return e.level; }); n = n || levels.length; var out = []; for (var i = 0; i < n; i++) out.push(generate('dark', levels[i % levels.length])); return out; }
  function levelFromScore(pct) { return Math.max(1, Math.min(60, Math.round((pct / 100) * 59) + 1)); }
  function strongestWeakest(breakdown) {
    var scored = (breakdown || []).filter(function (b) { return b.total > 0; }).map(function (b) { return { topic: b.topic, acc: b.ok / b.total }; });
    if (!scored.length) return { strongest: '', weakest: '', focusAreas: [] };
    scored.sort(function (a, b) { return b.acc - a.acc; });
    var strongest = scored[0].topic, weakest = scored[scored.length - 1].topic;
    var focusAreas = scored.slice().sort(function (a, b) { return a.acc - b.acc; }).slice(0, 3).map(function (s) { return s.topic; });
    return { strongest: strongest, weakest: weakest, focusAreas: focusAreas };
  }

  var QT_TYPES = [
    { key: 'persuasion', label: 'Persuasion & Influence' }, { key: 'biases', label: 'Cognitive Biases' }, { key: 'habits', label: 'Habits & Behaviour Change' },
    { key: 'emotion', label: 'Emotion & Decision-Making' }, { key: 'social', label: 'Social Psychology' }, { key: 'motivation', label: 'Motivation & Mindset' },
    { key: 'sales', label: 'Sales Psychology' },
    { key: 'mixed', label: 'Mixed Psychology Test' }
  ];
  var QT_DIFFICULTIES = ['Beginner', 'Intermediate', 'Advanced', 'Expert', 'Auto'];
  var QT_LENGTHS = [5, 10, 20, 50];
  function qtDifficultyToTier(diff) { return { Beginner: 1, Intermediate: 2, Advanced: 3, Expert: 4 }[diff] || 2; }
  function qtLevelToTier(level) { level = level || 1; if (level <= 15) return 1; if (level <= 30) return 2; if (level <= 45) return 3; return 4; }
  function qtTierToLevel(tier) { return { 1: 8, 2: 23, 3: 38, 4: 52 }[tier] || 23; }
  function qtQuestionForType(typeKey, tier) { var level = qtTierToLevel(tier); var key = typeKey === 'mixed' ? pick(POOL_KEYS) : typeKey; return generate(key, level); }
  function buildQuickTest(typeKey, difficulty, length, userLevel) {
    var tier = difficulty === 'Auto' ? qtLevelToTier(userLevel || 1) : qtDifficultyToTier(difficulty);
    var out = []; for (var i = 0; i < (length || 10); i++) out.push(qtQuestionForType(typeKey, tier));
    return out;
  }
  function generateDailyChallenge(userLevel) {
    var tier = qtLevelToTier(userLevel || 1);
    var mix = POOL_KEYS.concat(['persuasion', 'social']);
    var out = []; for (var i = 0; i < 8; i++) out.push(qtQuestionForType(mix[i % mix.length], tier));
    return out;
  }
  function checkAnswer(q, input) {
    var norm = function (s) { return (s || '').toLowerCase().trim().replace(/[^a-z0-9 ]/g, ''); };
    return norm(input) === norm(q.answer);
  }

  var LESSONS = {
    persuasion: {
      title: 'Persuasion & Influence',
      intro: 'Robert Cialdini\u2019s six principles explain most of the everyday psychology behind why people say yes \u2014 from advertising to negotiation to simple requests between friends.',
      origin: 'Cialdini\u2019s framework wasn\u2019t built in a lab first — he spent nearly three years in the late 1970s/early 1980s going undercover, training as a salesperson, fundraiser and marketer to observe which tactics actually worked in the wild, then traced each back to a psychological principle. This "participant observation" approach is why the six principles map so cleanly onto real advertising, sales scripts and negotiation tactics: they were reverse-engineered FROM professional persuaders\u2019 actual practice, not derived purely from theory first. His 1984 book "Influence" remains the most-cited applied psychology text in marketing and sales training worldwide.',
      sections: [
        { heading: 'Reciprocity Runs Deeper Than "Return a Favour"', body: 'Reciprocity isn\u2019t just etiquette — it\u2019s a deeply-wired social obligation found in virtually every human culture, likely because it enabled the trust-based cooperation early human groups needed to survive. The obligation triggers even from small, unsolicited, or unequal gifts: a free sample costing pennies can measurably increase a purchase worth far more, because the psychological debt feels disproportionate to the gift\u2019s actual value, not its price tag.' },
        { heading: 'Why Commitment Escalates', body: 'Once someone states or acts on a position — even a small, trivial one — cognitive dissonance creates pressure to stay consistent with it, because inconsistency feels uncomfortable and socially costly. This is why the "foot-in-the-door" technique works: a small early yes doesn\u2019t just make someone more agreeable, it subtly redefines their self-image as "the kind of person who helps with this," making the bigger ask feel like following through on who they already are, not a fresh decision.' },
        { heading: 'Social Proof Is Strongest Under Uncertainty', body: 'Social proof (looking to others\u2019 behaviour as a guide) is at its most powerful precisely when a decision is ambiguous or unfamiliar — which is why testimonials matter more for new or complex products than for something the buyer already understands well. It\u2019s also strongest when the "others" are seen as similar to the observer: proof from people "like me" persuades far more than proof from people who feel distant or dissimilar.' },
        { heading: 'Scarcity and Loss-Framing', body: 'Scarcity (limited availability) works because it reframes a decision from "should I gain this?" to "am I about to lose this?" — and loss aversion research shows potential losses are felt roughly twice as strongly as equivalent gains. This is why "only 3 left" or "sale ends tonight" is a persuasion staple: it isn\u2019t really about the item becoming more useful, it\u2019s about reframing inaction as a loss rather than a neutral non-decision.' }
      ],
      misconceptions: [
        { myth: 'Persuasion principles are manipulative tricks that only work on unintelligent people.', reality: 'These effects are largely automatic, evolved responses that operate on virtually everyone, including experts who study them — awareness reduces but doesn\u2019t eliminate their pull.' },
        { myth: 'Authority only works via genuine, relevant expertise.', reality: 'Surface markers of authority (a uniform, a title, confident tone) can trigger compliance even when the "authority" has no real relevant expertise.' },
        { myth: 'Scarcity is just an advertising gimmick with no real psychological basis.', reality: 'Scarcity taps into loss aversion, a well-documented and measurable bias in how humans weigh potential losses versus gains.' }
      ],
      expertNotes: [
        'Negotiators are trained to recognise which of the six principles is being used against them in real time, since naming the tactic measurably reduces its effect.',
        'Ethical marketers use principles like social proof and reciprocity transparently (real testimonials, genuine free trials) rather than fabricating scarcity or false authority.',
        'Cialdini later added a seventh principle, "unity" (shared identity, e.g. "as a fellow parent…"), noting it can be even more powerful than liking alone.'
      ],
      examples: [{ q: 'What persuasion principle does a testimonial-heavy landing page use?', working: 'It shows many other people already chose this product', answer: 'Social proof' }, { q: 'Why does a free trial increase eventual purchases?', working: 'Receiving something first creates a felt obligation', answer: 'Reciprocity' }]
    },
    biases: {
      title: 'Cognitive Biases',
      intro: 'Cognitive biases are predictable, systematic errors in thinking that shape decisions without us noticing \u2014 mostly mental shortcuts that are usually useful but sometimes badly mislead us.',
      origin: 'The modern study of cognitive bias began with Amos Tversky and Daniel Kahneman\u2019s work in the early 1970s, which challenged the assumption (central to classical economics) that humans make decisions rationally. Their research showed people instead rely on fast mental shortcuts ("heuristics") that work well most of the time but produce predictable, repeatable errors in specific situations. Kahneman won the 2002 Nobel Prize in Economics for this work (Tversky had died and was ineligible), and their 1979 "Prospect Theory" paper — explaining loss aversion mathematically — remains one of the most-cited papers in economics.',
      sections: [
        { heading: 'Why Biases Exist At All', body: 'Cognitive biases aren\u2019t random malfunctions — they\u2019re the byproduct of mental shortcuts that were "good enough" for the environments humans evolved in, trading some accuracy for speed. The availability heuristic (judging likelihood by how easily examples come to mind) was probably highly adaptive when "easily remembered" reliably meant "recently and locally relevant" — the problem is that modern media makes rare, dramatic events (plane crashes, shark attacks) far more memorable than common ones, breaking that old correlation.' },
        { heading: 'Loss Aversion Is Measurable, Not Just Anecdotal', body: 'Kahneman and Tversky\u2019s experiments found losses are felt roughly twice as intensely as equivalent gains — most people decline a fair 50/50 bet to win £100 or lose £100, even though the expected value is exactly zero either way. This asymmetry shows up everywhere from stock market panic-selling to why "avoid losing X" messaging outperforms "gain X" messaging of identical value in behaviour-change campaigns.' },
        { heading: 'Confirmation Bias Compounds Itself', body: 'Confirmation bias doesn\u2019t just affect what evidence we accept — it shapes what we even bother to SEARCH for in the first place, meaning people rarely even encounter strong counter-evidence to begin with. Combined with the availability heuristic, this creates a feedback loop: confirming information gets sought, noticed and remembered more, making it feel even more common and "obviously true" over time, regardless of the actual balance of evidence.' },
        { heading: 'Debiasing: What Actually Works (and What Doesn\u2019t)', body: 'Simply "being aware" of a bias barely reduces its effect in the moment — this itself is a well-replicated finding. What DOES work better: structured decision processes (e.g. deliberately listing reasons you might be WRONG before deciding), seeking out a specific disconfirming data point rather than "trying to be objective" in general, and building in a mandatory delay before high-stakes decisions to let strong emotional/availability effects fade.' }
      ],
      misconceptions: [
        { myth: 'Only unintelligent or uneducated people fall for cognitive biases.', reality: 'Bias strength is largely independent of intelligence — some studies find highly intelligent people are actually better at rationalising a biased conclusion after the fact.' },
        { myth: 'Knowing about a bias is usually enough to stop it affecting you.', reality: 'Awareness alone has repeatedly been shown to barely reduce most biases\u2019 real-world effect — structural changes to the decision process work far better.' },
        { myth: 'Cognitive biases are rare edge cases that only occasionally matter.', reality: 'They operate continuously, in ordinary everyday judgements, not just unusual high-stakes decisions — most people simply never notice them happening.' }
      ],
      expertNotes: [
        'Behavioural economists design "choice architecture" (default options, framing) around known biases rather than trying to train the bias away.',
        'Investment professionals build mandatory checklists specifically to counter loss aversion and confirmation bias during high-stakes decisions.',
        'Kahneman\u2019s own later work stressed that even experts who teach these biases remain susceptible to them in their own snap judgements.'
      ],
      examples: [{ q: 'Why do people keep watching a bad film "since I\u2019ve already paid for the ticket"?', working: 'Past, unrecoverable cost is influencing a decision that should only weigh future value', answer: 'The sunk cost fallacy' }, { q: 'Why do people overestimate shark attack risk after seeing news coverage?', working: 'A vivid, memorable example feels statistically more common than it is', answer: 'The availability heuristic' }]
    },
    habits: {
      title: 'Habits & Behaviour Change',
      intro: 'Habits form through a simple, repeatable loop \u2014 and understanding that loop is the single most reliable lever for building new behaviours or breaking old ones.',
      origin: 'Habit formation research draws on a mix of neuroscience and behavioural psychology going back to B.F. Skinner\u2019s mid-20th-century work on conditioning, but the modern applied framework (the "habit loop" and its business/self-help popularisation) largely traces to Charles Duhigg\u2019s 2012 book "The Power of Habit," itself built on decades of MIT neuroscience research showing habitual behaviour is processed differently in the brain than deliberate, conscious decision-making. B.J. Fogg\u2019s Behavior Model, developed at Stanford, later formalised WHY specific interventions succeed or fail by breaking behaviour down into motivation, ability and prompts.',
      sections: [
        { heading: 'The Habit Loop Is a Neurological Shortcut', body: 'MIT neuroscience research (led by Ann Graybiel) found that as a behaviour becomes habitual, brain activity in the basal ganglia "chunks" the whole cue-routine-reward sequence into a single automatic unit, while activity in the deliberate, effortful prefrontal cortex actually DECREASES. This is why habits feel effortless once established (you\u2019re barely "deciding" anymore) and also why they\u2019re so hard to consciously override in the moment — the automatic pathway fires before slower deliberate thought catches up.' },
        { heading: 'Implementation Intentions Close the Intention-Action Gap', body: 'Peter Gollwitzer\u2019s research found that simply forming a goal ("I want to exercise more") barely predicts whether people actually follow through, but a specific if-then plan ("If it\u2019s 7am, I will put on my running shoes") dramatically increases follow-through rates across dozens of studies. The mechanism: pre-deciding the response to a specific cue removes the in-the-moment willpower cost of deciding whether to act, since the decision was already made in advance, calmly, without competing temptations present.' },
        { heading: 'The "21 Days" Myth vs the Real Research', body: 'The popular claim that habits take 21 days to form has no solid evidence behind it — it likely originated from a 1960s plastic surgeon\u2019s informal observation about patients adjusting to appearance changes, not habit formation research at all. A 2010 University College London study actually measuring habit formation found it took a median of 66 days for a behaviour to become automatic, with a huge range (18 to 254 days) depending on the behaviour\u2019s complexity and the person — the real number is far more variable and far larger than the popular myth suggests.' },
        { heading: 'Why Removing Friction Beats Building Willpower', body: 'B.J. Fogg\u2019s model shows behaviour requires motivation, ability AND a prompt to converge simultaneously — and since motivation naturally fluctuates day to day, relying on it is inherently unreliable. Deliberately lowering the ABILITY threshold (making the desired behaviour easier — laying out gym clothes, keeping a water bottle visible) is a more dependable lever than trying to boost motivation, because it works even on a low-motivation day, which is exactly when habits are most likely to break.' }
      ],
      misconceptions: [
        { myth: 'It takes exactly 21 days to build a new habit.', reality: 'Real research found a median of 66 days, with actual range spanning weeks to many months depending on the behaviour and person.' },
        { myth: 'Relapsing into an old habit means the change attempt has failed.', reality: 'The Stages of Change model treats relapse as a normal loop back to an earlier stage — most successful changes involve several attempts, not one clean success.' },
        { myth: 'Building a habit is mostly about willpower and self-discipline.', reality: 'Removing friction and redesigning the environment (ability and prompts) reliably outperforms relying on willpower alone.' }
      ],
      expertNotes: [
        'Behaviour-change coaches assess motivation, ability AND prompt separately when a habit isn\u2019t sticking, rather than assuming "not enough willpower."',
        'Habit stacking (attaching a new habit to an already-automatic one) borrows the existing habit\u2019s reliable cue rather than requiring a brand-new one.',
        'Environment design (what\u2019s visible, accessible, or the default option) is treated as a primary lever in clinical behaviour-change programmes, not an afterthought.'
      ],
      examples: [{ q: 'Why does laying out gym clothes the night before help you actually go?', working: 'It lowers the ability/effort barrier at the moment the prompt appears', answer: 'It removes friction, making the behaviour easier to start' }, { q: 'What loop element does "reward" belong to?', working: 'Cue \u2192 routine \u2192 reward', answer: 'The habit loop' }]
    },
    emotion: {
      title: 'Emotion & Decision-Making',
      intro: 'Far from being a distraction from "rational" thinking, emotion is deeply woven into how humans actually make decisions \u2014 for better and for worse.',
      origin: 'For most of the 20th century, mainstream psychology and economics treated emotion as noise that corrupted "rational" decision-making. That view was overturned largely by neuroscientist Antonio Damasio\u2019s research in the 1990s on patients with damage to the brain\u2019s emotion-processing regions (like the ventromedial prefrontal cortex): these patients retained normal logical reasoning ability but became strikingly unable to make everyday decisions efficiently, because they no longer had the emotional "gut feelings" that normally narrow down options quickly. This led directly to his "somatic marker hypothesis" — that emotion is not opposed to good decision-making but a necessary part of it.',
      sections: [
        { heading: 'The Affect Heuristic Substitutes Feeling for Analysis', body: 'The affect heuristic describes how, under time pressure or complexity, people substitute "how do I feel about this?" for a genuinely effortful cost-benefit analysis — and remarkably, this shortcut often produces reasonably good real-world decisions quickly, which is likely why it persists. The risk is that it can be hijacked by irrelevant emotional cues (background music, an attractive spokesperson) that have nothing to do with the actual merits of a decision, but still shift the "feeling" being consulted.' },
        { heading: 'Cognitive Dissonance as a Self-Justification Engine', body: 'Leon Festinger\u2019s original 1950s research (studying a doomsday cult after its prophecy failed) found something counter-intuitive: believers didn\u2019t abandon their belief when proven wrong — many became MORE committed, generating new justifications to resolve the discomfort. This established that dissonance reduction often works by changing the belief or story, not the behaviour, which is why post-purchase rationalisation, sunk-cost persistence, and "I meant to do that" logic are all so psychologically stubborn.' },
        { heading: 'Arousal and Performance: Why "Some Nerves" Help', body: 'The Yerkes-Dodson law (originally from 1908 animal-learning experiments, since replicated widely in humans) shows performance follows an inverted U-shape against arousal: too little pressure produces under-engagement, too much produces anxiety that crowds out working memory, and performance peaks somewhere in the middle. Critically, the OPTIMAL arousal level shifts lower for complex or unfamiliar tasks and higher for simple, well-practised ones — which is why elite performers under extreme pressure (a well-rehearsed skill) can outperform their calm-practice level, while a novice under the same pressure typically collapses.' },
        { heading: 'Emotional Contagion Spreads Without Conscious Awareness', body: 'Emotional contagion — catching someone else\u2019s mood — happens partly through unconscious mimicry of facial expression, posture and vocal tone, and measurably influences group mood, negotiation outcomes and even consumer behaviour in retail environments. This is why a single visibly stressed or enthusiastic team member can measurably shift an entire meeting\u2019s emotional tone, often faster than any spoken argument could.' }
      ],
      misconceptions: [
        { myth: 'Good decisions are purely logical and should exclude emotion entirely.', reality: 'Damasio\u2019s patient research found people who lost access to emotional signals became WORSE, not better, at everyday practical decisions.' },
        { myth: 'More pressure/arousal always improves performance ("rising to the occasion").', reality: 'The Yerkes-Dodson law shows performance follows an inverted U — too much arousal reliably degrades performance, especially on complex tasks.' },
        { myth: 'Rationalising a decision after the fact means you\u2019re lying to yourself.', reality: 'Post-hoc rationalisation via cognitive dissonance is a normal, largely unconscious process nearly everyone does, not a sign of unusual dishonesty.' }
      ],
      expertNotes: [
        'Clinical neuropsychologists use somatic-marker research to explain why purely "logical" financial or ethical reasoning training often fails without addressing emotional signals.',
        'Performance coaches deliberately tune arousal levels (calming or activating an athlete/performer) rather than assuming maximum focus always means maximum pressure.',
        'Negotiators are trained to notice and interrupt emotional contagion early in high-stakes talks, since one party\u2019s visible frustration can unconsciously spread and derail the room.'
      ],
      examples: [{ q: 'Why might someone rationalise an expensive purchase as "worth it" right after buying it?', working: 'Reduces the discomfort between "I spent a lot" and "was that wise?"', answer: 'Cognitive dissonance' }, { q: 'Why does mild pre-exam nervousness often help performance, while extreme panic hurts it?', working: 'Performance peaks at moderate arousal, drops off at very low or very high arousal', answer: 'The Yerkes-Dodson law' }]
    },
    social: {
      title: 'Social Psychology',
      intro: 'Some of psychology\u2019s most famous experiments reveal just how powerfully group presence, authority and social context shape individual behaviour.',
      origin: 'Social psychology\u2019s most influential findings emerged from a remarkable run of experiments in the 1950s-70s, often prompted by real historical events. Solomon Asch\u2019s conformity experiments (1951) explored how readily people abandon their own correct judgement to match a group. Stanley Milgram\u2019s obedience experiments (1961, deliberately begun the year Adolf Eichmann\u2019s trial started) tested how far ordinary people would go under an authority figure\u2019s instruction. Philip Zimbardo\u2019s Stanford Prison Experiment (1971) explored how quickly ordinary people adopt abusive roles within an institutional structure. All three remain among the most-cited (and most ethically debated) studies in psychology\u2019s history.',
      sections: [
        { heading: 'Asch: Conformity Even on Obvious Answers', body: 'Asch\u2019s participants were shown a simple line-length comparison with an obvious correct answer, seated among actors instructed to confidently give the SAME wrong answer aloud first. Around a third of genuine participants conformed to the group\u2019s wrong answer at least once, despite the task being unambiguous — and follow-up interviews found many didn\u2019t even believe the group, they simply couldn\u2019t bear the social discomfort of visibly disagreeing. Conformity dropped sharply the moment even ONE other person in the room also gave the correct answer, showing how fragile group pressure is against just one visible ally.' },
        { heading: 'Milgram: Obedience Under Authority', body: 'In Milgram\u2019s original study, ordinary volunteers were instructed by an authority figure (a researcher in a lab coat) to administer what they believed were increasingly painful, then dangerous, electric shocks to another person for wrong answers on a memory test. A striking majority continued to the maximum voltage simply because the authority figure calmly insisted they continue — not because participants were unusually cruel, but because the situational pressure of a legitimate-seeming authority overrode many people\u2019s independent moral judgement. The result has been replicated (with ethical modifications) in multiple countries and eras, suggesting it reflects something durable about situational obedience, not a one-off historical artefact.' },
        { heading: 'The Bystander Effect Is About Diffusion, Not Apathy', body: 'The bystander effect — people being less likely to help in an emergency as more witnesses are present — is driven by diffusion of responsibility (each individual feels less personally obligated when others could also act) and social influence (each person looks to others\u2019 lack of reaction as a cue that maybe it\u2019s not actually an emergency). Critically, research shows the fix isn\u2019t "convincing bystanders to care more" — training people to break the diffusion explicitly (e.g. pointing directly at one bystander: "you, call an ambulance") reliably restores individual action.' },
        { heading: 'Groupthink: When Cohesion Undermines Judgement', body: 'Irving Janis coined "groupthink" analysing real historical decision-making failures (including the Bay of Pigs invasion), finding that highly cohesive groups under pressure to reach consensus often suppress critical evaluation and dissenting views to preserve group harmony. The antidote used in modern high-stakes decision-making (corporate boards, government cabinets) is structural: assigning a designated "devil\u2019s advocate," seeking outside opinions, and explicitly inviting disagreement BEFORE a decision is made, not just tolerating it after.' }
      ],
      misconceptions: [
        { myth: 'Milgram\u2019s results only reflect a uniquely obedient generation or culture from the 1960s.', reality: 'Modified, ethical replications across many countries and later decades have found broadly similar high-obedience rates.' },
        { myth: 'The bystander effect happens because people in groups are more callous.', reality: 'It\u2019s driven by diffusion of responsibility and social cue-following, not reduced caring — clear, direct requests for help reliably break the effect.' },
        { myth: 'Groupthink only happens in obviously dysfunctional or unintelligent groups.', reality: 'Janis specifically studied highly capable, intelligent decision-makers — cohesion and pressure for consensus can undermine judgement regardless of individual intelligence.' }
      ],
      expertNotes: [
        'Crisis-response training now explicitly teaches "pointing and naming" a specific bystander, because it reliably defeats diffusion of responsibility.',
        'Corporate governance experts recommend a rotating, explicitly-assigned devil\u2019s advocate role in high-stakes board decisions to counter groupthink structurally.',
        'Modern obedience research focuses less on "would people obey" and more on what specific situational factors (proximity, legitimacy, gradual escalation) increase or reduce it.'
      ],
      examples: [{ q: 'Why might nobody call for help when many people witness an emergency?', working: 'Responsibility feels diffused across everyone present', answer: 'The bystander effect' }, { q: 'You explain a colleague\u2019s lateness as "he\u2019s unreliable" but your own as "traffic was bad" \u2014 what is this?', working: 'Character blamed in others, circumstance blamed for yourself', answer: 'The fundamental attribution error' }]
    },
    motivation: {
      title: 'Motivation & Mindset',
      intro: 'What actually drives sustained effort and performance turns out to be more about autonomy, mindset and fit-to-challenge than about rewards and willpower alone.',
      origin: 'Edward Deci\u2019s early 1970s experiments were the starting point for modern motivation science: he found that paying people for a puzzle they already enjoyed actually REDUCED how much they voluntarily kept doing it afterwards compared to an unpaid group — a direct challenge to the assumption that more reward always means more motivation. This "overjustification effect" led Deci and Richard Ryan to develop Self-Determination Theory through the 1980s-2000s. Around the same period, Carol Dweck\u2019s research on how children respond to failure led to the "growth vs fixed mindset" framework, and Mihaly Csikszentmihalyi\u2019s interviews with artists, athletes and surgeons in the 1970s produced the concept of "flow."',
      sections: [
        { heading: 'Why External Rewards Can Backfire', body: 'The overjustification effect shows that adding an external reward to an already-enjoyable activity can shift the perceived REASON for doing it — from "I do this because I enjoy it" to "I do this for the reward" — so that once the reward stops, motivation can drop below even the original, unpaid baseline. This doesn\u2019t mean rewards are always bad — for boring or effortful tasks with no intrinsic enjoyment to undermine, external rewards still reliably increase effort — but for already-enjoyed activities, added rewards are a genuine risk, not a free boost.' },
        { heading: 'The Three Needs Behind Real Motivation', body: 'Self-Determination Theory\u2019s core finding, replicated across work, education, sport and health behaviour research, is that sustained intrinsic motivation depends on three psychological needs being met: autonomy (feeling like your actions are self-chosen, not just controlled by others), competence (feeling capable and able to improve), and relatedness (feeling connected to others in the activity). Undermining any single one of these — even while other conditions look good on paper (high pay, clear goals) — reliably weakens motivation over time.' },
        { heading: 'Growth Mindset Changes How Failure Is Processed', body: 'Dweck\u2019s research found children praised for INTELLIGENCE ("you\u2019re so smart") became more likely to avoid challenging tasks afterward, fearing failure would contradict that fixed trait; children praised for EFFORT/STRATEGY became more willing to attempt harder tasks, since failure there just meant "try a different strategy," not "I\u2019m not smart." This is why the specific WORDING of praise and feedback (process-focused vs trait-focused) has become a major applied focus in education research, not just an abstract philosophical point about mindset.' },
        { heading: 'Flow Requires a Precise Challenge-Skill Match', body: 'Csikszentmihalyi found "flow" — complete absorption with distorted, usually-faster sense of time — emerges specifically when perceived challenge and perceived skill are both high AND closely matched; too far below skill produces boredom, too far above produces anxiety, and only the narrow zone in between produces flow. This is why well-designed games, sports training and deliberate practice deliberately escalate difficulty as skill improves — keeping a person continuously inside that narrow "flow channel" rather than at a fixed difficulty level.' }
      ],
      misconceptions: [
        { myth: 'Paying someone more always increases their motivation to do a task.', reality: 'For already-enjoyable tasks, added external reward can measurably REDUCE intrinsic motivation once the reward is removed (the overjustification effect).' },
        { myth: 'A growth mindset just means "believing in yourself."', reality: 'It specifically means believing ABILITY can be developed through effort and strategy — the actual mechanism is how failure gets interpreted, not general optimism.' },
        { myth: '"Flow" happens whenever you\u2019re relaxed and comfortable doing something familiar.', reality: 'Flow specifically requires HIGH challenge closely matched to high skill — comfortable, easy tasks typically produce boredom, not flow.' }
      ],
      expertNotes: [
        'Coaches and educators are trained to praise process and strategy ("great approach") rather than fixed traits ("you\u2019re so talented") specifically because of Dweck\u2019s findings.',
        'Workplace motivation consultants audit autonomy, competence and relatedness separately when engagement drops, rather than assuming pay is the only lever.',
        'Game and instructional designers deliberately track a user\u2019s skill level to keep difficulty inside the "flow channel" rather than fixed at one setting.'
      ],
      examples: [{ q: 'Why can paying someone for a hobby they loved sometimes make them enjoy it less?', working: 'An external reward can crowd out the original intrinsic motivation', answer: 'The overjustification effect' }, { q: 'What three needs does Self-Determination Theory say drive motivation?', working: 'Deci & Ryan\u2019s core framework', answer: 'Autonomy, competence and relatedness' }]
    },
    sales: {
      title: 'Sales Psychology',
      intro: 'Selling well is applied psychology \u2014 it is about asking the right questions in the right order, framing the same information in ways that land differently, and positioning yourself so people trust your judgement before you\u2019ve even made an offer.',
      origin: 'Modern sales psychology draws directly on Cialdini\u2019s persuasion principles and on decades of applied research from professional sales training (SPIN Selling, consultative/needs-based selling models developed through the 1980s-90s) that shifted the field away from pushy, feature-dumping "hard sell" pitches toward question-led, problem-diagnosis approaches. The underlying idea, backed by research into how people actually make buying decisions: people rarely buy because they were told enough facts \u2014 they buy when they feel understood, when the offer is framed around their own stated problem, and when they trust the person offering the solution.',
      sections: [
        { heading: 'Discovery Comes Before the Pitch', body: 'Consultative selling flips the traditional order: instead of leading with features and benefits, a skilled salesperson spends the early part of a conversation almost entirely asking open questions to surface the prospect\u2019s actual pain point, its cost, and what a good outcome would look like. This matters because a pitch built on a guessed-at problem persuades far less than one built on the prospect\u2019s own words \u2014 people trust conclusions more when they feel like they led the salesperson to them, not the other way round.' },
        { heading: 'Framing Questions Steer the Conversation Without Pressure', body: 'The exact phrasing of a question changes the answer it invites, not just the tone. A presupposition question ("When would you like to get started?") assumes the sale is already happening and skips past "whether" to "when" or "which" \u2014 without ever sounding pushy, because it\u2019s still phrased as an open, friendly question. An either/or close ("Tuesday or Thursday?") works the same way: both answers move the conversation forward, removing the easy binary "no" that a closed yes/no question invites.' },
        { heading: 'Framing Phrases Change How the Same Facts Feel', body: 'Identical information lands differently depending on the words wrapped around it \u2014 this is a framing effect, the same mechanism behind Kahneman and Tversky\u2019s "90% fat-free" vs "10% fat" findings. Saying "investment" instead of "cost" reframes a number from an expense to a value-generating action. Asking what the current situation is "costing" someone in time, stress or money reframes inaction itself as a loss, tapping into loss aversion rather than relying on the appeal of a gain. None of this changes the facts \u2014 it changes which facts feel most salient.' },
        { heading: 'Authority Is Built, Not Claimed', body: 'Saying "trust me, I\u2019m an expert" does very little \u2014 real authority positioning works by demonstration: leading with a specific, verifiable result ("47 businesses, last year, this exact problem") rather than a vague claim, speaking in confident, direct recommendations rather than hedged language ("I think this might maybe help"), and borrowing credibility from trusted third parties (press features, expert endorsements, client case studies) rather than only asserting it yourself. Each of these taps a real, separately-studied persuasion effect \u2014 specificity, confident framing, and Cialdini\u2019s social proof/authority principles \u2014 working together rather than any single "authority trick."' },
        { heading: 'Objections Are Data, Not a Fight to Win', body: 'A stall like "I need to think about it" is rarely the real objection \u2014 it\u2019s usually a vague placeholder for a specific concern (price, timing, trust, a stakeholder who isn\u2019t in the room) that the prospect either hasn\u2019t identified themselves yet or doesn\u2019t want to say aloud. Techniques like "feel, felt, found" validate the concern first (reducing defensiveness) before reframing it with evidence, and a narrowing either/or question ("is it the timing, the price, or something else?") turns a vague stall into something specific and actually addressable \u2014 arguing directly against a vague objection almost never works, because there is nothing concrete yet to respond to.' }
      ],
      misconceptions: [
        { myth: 'Good salespeople are naturally charismatic talkers who can sell anything to anyone.', reality: 'The strongest predictor of sales success in modern research is disciplined questioning and listening, not talking \u2014 top performers typically let the prospect do most of the talking early on.' },
        { myth: 'Framing and authority-positioning are manipulative because they don\u2019t change the underlying facts.', reality: 'These techniques are ethically neutral tools \u2014 the same framing and specificity used to sell a genuinely good solution honestly is identical in mechanism to the version used to oversell a bad one; the ethics live in whether the underlying claim is true, not in the framing itself.' },
        { myth: 'Using scarcity or urgency in a pitch is always a manipulative dark pattern.', reality: 'The determining factor is whether the scarcity or deadline is real \u2014 a genuinely limited intake or a real seasonal deadline respects the buyer\u2019s informed choice; a fabricated countdown timer does not, even though both use the identical psychological lever.' },
        { myth: 'An objection means the prospect has decided not to buy.', reality: 'Most objections are under-specified stalls, not final decisions \u2014 treating them as a request for more specific information, rather than a rejection, resolves the majority of them.' }
      ],
      expertNotes: [
        'Sales trainers score call recordings on talk-to-listen ratio, since the strongest closers typically talk noticeably less than average during discovery.',
        'Positioning-focused sales frameworks (e.g. "guide, not hero" messaging) deliberately centre the client\u2019s outcome rather than the seller\u2019s credentials, on the finding that this reads as more trustworthy, not less confident.',
        'Experienced negotiators are trained to stay silent after stating a number, since filling that silence themselves (e.g. with an unprompted discount) reliably gives away leverage for free.'
      ],
      examples: [{ q: 'Why does "When would you like to get started?" work better than "Do you want to go ahead?"', working: 'It presupposes the decision is already made, skipping past "whether" to "when"', answer: 'A presupposition (assumptive) question' }, { q: 'Why say "investment" instead of "cost" for the same number?', working: 'It reframes the same figure as value-generating rather than as an expense', answer: 'A framing effect' }]
    },
    dark: {
      title: 'Dark Psychology & Manipulation Tactics',
      intro: 'This section exists so you can recognise manipulation, coercive control and high-control-group tactics when they happen to you or someone you know — not to help anyone perform them. Every technique below is explained through the lens of "how do I spot this and get out," because understanding a manipulator’s playbook is the single most effective defence against it.',
      origin: 'The academic study of manipulative personality traits goes back to Machiavelli’s 16th-century "The Prince," but the modern "Dark Triad" framework — narcissism, Machiavellianism and psychopathy — was formalised by psychologists Delroy Paulhus and Kevin Williams in 2002. In parallel, domestic-violence researcher Evan Stark’s work on "coercive control" (which became UK law in 2015) and sociologist Robert Lifton’s 1961 study of thought-reform in Chinese re-education camps gave clinicians and advocates a shared vocabulary for patterns that used to be dismissed as just "a difficult relationship" or "a strict group." That vocabulary — gaslighting, DARVO, love bombing, milieu control — is now used by therapists, domestic-abuse charities and cult-recovery specialists specifically to help people name and exit these situations.',
      sections: [
        { heading: 'Why This Is Framed as Defence, Not Offence', body: 'Every tactic here already exists in the world whether or not you learn about it — abusers, cult recruiters and manipulative salespeople use these patterns regardless of whether their targets can name them. Research on coercive control consistently finds that victims who can put a specific name to what’s happening ("this is DARVO," "this is love bombing") recover their footing faster than those who only have a vague, confusing sense that something is wrong. Naming a pattern is what lets you stop absorbing the blame for it.' },
        { heading: 'The Dark Triad Isn’t Rare, and Isn’t Always Obvious', body: 'Subclinical levels of narcissism, Machiavellianism and psychopathy are common in the general population — most manipulators aren’t diagnosable "psychopaths" in a clinical sense, just people scoring higher on these traits than average. They’re also often charming and high-functioning at first: charisma and manipulation skill frequently travel together, which is exactly why love bombing works so well as an opening move.' },
        { heading: 'Gaslighting: Attacking the Target’s Own Perception', body: 'Gaslighting works by repeatedly, confidently contradicting something the target directly experienced — a conversation, an event, a promise — until they start to doubt their own memory rather than the other person’s honesty. It rarely arrives as one dramatic lie; it builds through dozens of small denials ("that never happened," "you’re remembering it wrong," "you’re so sensitive") until the target’s baseline trust in their own judgement erodes. The reliable counter is external: writing things down as they happen, or checking against someone outside the relationship, restores a reference point the tactic depends on removing.' },
        { heading: 'Love Bombing and Intermittent Reinforcement Work Together', body: 'Love bombing (early excessive affection, gifts and attention) and intermittent reinforcement (unpredictable warmth followed by coldness) are usually two phases of the same pattern, not separate tactics. The first phase builds an intense, fast attachment; the second phase — switching unpredictably between affection and withdrawal — is what makes that attachment so hard to walk away from, because unpredictable reward schedules produce stronger, more persistent pursuit behaviour than steady, reliable affection ever does. Recognising the switch from constant warmth to intermittent warmth is often the clearest early signal that the relationship has moved from genuine into strategic.' },
        { heading: 'DARVO: Deny, Attack, Reverse Victim and Offender', body: 'When confronted about their own behaviour, a person using DARVO denies it happened, attacks the character or credibility of whoever raised it, then reframes themselves as the one being victimised. It’s effective because it forces the original point (the behaviour that was raised) off the table entirely — the conversation becomes about defending against the counter-attack instead. Naming the pattern out loud, even silently to yourself ("this is DARVO"), is usually enough to stop it from working, because it restores the original topic as the thing that actually needs addressing.' },
        { heading: 'Triangulation and Negging Both Exploit Approval-Seeking', body: 'Triangulation (unfavourably comparing a partner to an ex, coworker or friend) and negging (a backhanded compliment) both work the same way: they manufacture a small dose of insecurity, then position the manipulator as the source of the approval that would resolve it. Neither requires ongoing contact with the "comparison" person to be effective — the comparison itself is the tool. Once the pattern is visible, the instinct it triggers (working harder to win approval) is worth treating as information about the tactic, not about your own adequacy.' },
        { heading: 'Coercive Control Is a Pattern, Not an Incident', body: 'What makes coercive control (now a criminal offence in the UK) so hard to recognise from the inside is that no single action looks severe enough to justify leaving — a monitored phone here, an isolating comment about a friend there. It’s the cumulative, ongoing restriction of someone’s freedom and independent judgement that constitutes the abuse, which is why "why didn’t you just leave after the first sign?" fundamentally misunderstands how the pattern works.' },
        { heading: 'The Same Mechanisms Scale From One Person to a Whole Group', body: 'Lifton’s eight criteria for cult thought-reform (milieu control, loaded language, demand for purity, and others) describe the same underlying moves used by a single controlling partner — restricting outside information, discouraging independent friendships, making the group/person the sole source of truth — just applied at the scale of a whole community instead of one relationship.' },
        { heading: 'Propaganda Techniques Aren’t Just Historical', body: 'Edward Bernays’ insight — that mass opinion moves more reliably through unconscious emotional association and group identity than through logical argument — is the same mechanism visible in modern advertising, political messaging and cult recruitment material. The tell isn’t the specific medium; it’s whether a message is asking you to feel something and belong to something, or asking you to evaluate a claim on its merits. Noticing which one is happening is a transferable skill across all three contexts.' },
        { heading: 'Grey Rocking: A Defensive Tactic, Not a Winning Move', body: 'Grey rocking — becoming deliberately flat, unresponsive and uninteresting to engage with — works by removing the emotional reaction a manipulator is specifically seeking, making continued engagement unrewarding for them over time. It isn’t about "winning" an argument or getting the other person to admit anything; it’s a disengagement tool for situations where full no-contact isn’t immediately possible (a shared workplace, co-parenting, a family event), used to reduce the payoff they get from provoking a reaction.' },
        { heading: 'Boundary Testing Is How Coercive Relationships Usually Begin', body: 'Rather than one large violation, coercive relationships typically start with a small boundary being tested — a minor comment, a slightly-too-personal question, a small ask — followed by watching whether it produces resistance. Each individual step looks minor enough that no single one seems worth objecting to, which is exactly why the pattern is hard to notice from inside it. Treating a small crossed boundary as data (not as an isolated, forgivable one-off) is the practical defence.' },
        { heading: 'Sexual and Reproductive Coercion Are Part of Coercive Control, Not a Separate Category', body: 'Coercive control frameworks explicitly include sexual and reproductive coercion alongside the tactics above — pressuring or guilting someone into sex, sabotaging contraception, or using intimacy strategically as a reward or punishment. None of this requires physical force to count: consent given under repeated pressure, guilt, or exhaustion is not the same as a free "yes," and consent to one act, on one occasion, doesn’t automatically extend to the next. This applies the same way regardless of gender or relationship history — the mechanism (pressure eroding a genuine choice) is what matters, not who is doing it to whom.' },
        { heading: 'There Is No Pinocchio’s Nose — Forget the "One Tell" Myth First', body: 'The single most important finding in real deception research is a negative one: no single behaviour — not avoiding eye contact, not touching the face, not crossing arms — reliably indicates lying. A meta-analysis pooling over 200 studies (Bond & DePaulo) found human accuracy at spotting lies from isolated cues sits around 54%, barely above a coin flip, even among trained professionals. Anyone who tells you a single confident "tell" gives someone away is teaching pop psychology, not the real research — which is exactly why the skills below focus on baselines and clusters, not gotcha gestures.' },
        { heading: 'Baseline First, Deviation Second', body: 'The entire foundation of real behavioural detection — used by interviewers, negotiators and detectives alike — is establishing how a specific person normally looks, sounds and moves BEFORE reading anything into a change. Someone who naturally speaks quickly, avoids eye contact, or fidgets isn’t showing anything meaningful by continuing to do so; what matters is a genuine DEVIATION from their own established baseline, ideally timed to a specific question or moment, not a comparison to some imagined "average person."' },
        { heading: 'Micro-Expressions: The Real Science Behind the Show', body: 'Paul Ekman’s Facial Action Coding System (FACS) — the actual psychological research the character Patrick Jane in The Mentalist is loosely based on — catalogued the specific facial muscle movements behind seven core emotions (anger, contempt, disgust, fear, happiness, sadness, surprise) and found them to be universal across cultures, even among isolated groups with no exposure to outside media. A micro-expression is a genuine emotional signal leaking through for under half a second before someone consciously masks it. In fiction this looks like instant mind-reading; in reality it takes real training (Ekman built a training tool, the METT, specifically because it doesn’t come naturally) and works best combined with everything else in this section, not alone.' },
        { heading: 'Statement Analysis: What Someone’s Own Words Reveal', body: 'Forensic statement analysis studies patterns in HOW people describe events, not just what they claim happened. Distancing language ("mistakes were made" instead of "I made a mistake") quietly reduces ownership of an action. Unexplained tense shifts mid-story can suggest a rehearsed account rather than a genuine memory. Unprompted, excessive qualifiers in a denial ("I did not, to the best of my recollection...") can signal someone hedging against a future contradiction. None of these prove anything alone — real analysts treat each one as a prompt to ask a specific, gentle follow-up question, not as a verdict.' },
        { heading: 'Cognitive Load: Why Follow-Up Questions Matter More Than Stares', body: 'Lying is measurably more mentally demanding than telling the truth, because a fabricated account has to be invented, tracked for consistency, and defended against contradiction all at once, while a true memory just has to be retrieved. This is why real cognitive-interview techniques — asking someone to recount events in reverse order, or adding unexpected follow-up detail questions — work far better than staring someone down: they increase the mental load a fabricated story has to survive, rather than hoping to spot a single physical giveaway.' },
        { heading: 'Reading Changes in People Over Time, Not Just in One Conversation', body: 'The slowest but most trustworthy version of this skill isn’t catching one lie in one conversation — it’s noticing when someone’s own normal pattern genuinely shifts over days or weeks: a talkative person going quiet, a reliable person becoming erratic, a confident person growing guarded. Because it’s measured against that specific person’s own real baseline over real time, this kind of change is far harder to fake and far more informative than any single tell — it’s also exactly the kind of shift worth checking in on someone about, not just "detecting."' },
        { heading: 'What "Detective-Level" Observation Actually Is (and Isn’t)', body: 'TV mentalists and cold readers appear to deduce a stranger’s life story from a glance — the real skill behind that is extremely high-resolution observation (a scuffed shoe, a tan line, a particular turn of phrase) combined with knowing what’s statistically likely true of most people, delivered with confident showmanship. It also leans on the Barnum effect: vague, generic-sounding statements ("you sometimes doubt yourself, but you’re also quite resilient") feel eerily personal to almost anyone, because they’re built to apply broadly. Understanding both halves — real observation skill AND the Barnum effect that makes vague guesses feel specific — is itself a defensive skill against being cold-read or "mentalised" by someone else.' },
        { heading: 'The Honest Limit: Clusters Over Certainty', body: 'Every credible source in this field agrees on the same caution: even trained police, judges and polygraph examiners perform only slightly better than chance at detecting lies without other corroborating evidence. The realistic, honest version of "detective-level" skill isn’t infallible lie detection — it’s noticing baseline deviations, clustering multiple signals together, and asking better, more specific follow-up questions instead of accusing based on a single gesture. Treat every signal in this section as a reason to look closer and ask, never as proof on its own.' }
      ],
      misconceptions: [
        { myth: 'Manipulators are easy to spot — they’re obviously cold, cruel or unpleasant.', reality: 'The most effective manipulators are often the most charming, likeable and generous-seeming people in the room, especially at first — that charm is frequently part of the tactic, not evidence against it.' },
        { myth: 'This only happens in romantic relationships.', reality: 'Gaslighting, DARVO and coercive control appear in workplaces, families, friendships and organised groups just as often as in romantic partnerships.' },
        { myth: 'If it were really manipulation, I’d have noticed it happening in the moment.', reality: 'These tactics are specifically effective BECAUSE they’re gradual and hard to notice in real time — that’s not a personal failure, it’s the entire mechanism working as designed.' },
        { myth: 'Coercion only counts if physical force was used.', reality: 'Sustained pressure, guilt, wearing someone down, or gradually testing and pushing past a boundary can override genuine consent just as much as force can — and it affects men and women alike.' },
        { myth: 'Someone who loves you intensely and immediately is showing how much they care.', reality: 'Genuine affection usually builds at a pace that matches how well two people actually know each other — intensity that arrives before that knowledge does is one of the most consistent early warning signs in coercive-control research, not proof of depth of feeling.' },
        { myth: 'If I can’t point to one bad incident, I don’t have a right to feel uneasy.', reality: 'Coercive control is specifically defined by researchers as a pattern rather than an incident — the unease itself, building across many small moments, is valid evidence worth taking seriously on its own.' },
        { myth: 'Avoiding eye contact is a reliable sign someone is lying.', reality: 'A meta-analysis of over 200 studies found accuracy from isolated cues like this sits around 54%, barely above chance — eye contact varies hugely by person, culture and simple nervousness.' },
        { myth: 'Trained detectives and experts can basically always tell when someone is lying.', reality: 'The same research found trained professionals (police, judges, polygraph examiners) perform only slightly better than untrained people without other corroborating evidence.' },
        { myth: 'Reading micro-expressions means you can see straight through anyone, instantly, like on TV.', reality: 'Micro-expressions are a real, studied phenomenon, but reliably catching them takes real training and works best combined with baseline, statement analysis and context — not as a stand-alone superpower.' },
        { myth: 'A cold reader or "mentalist" who nails details about a stranger must have some kind of genuine intuition or gift.', reality: 'It’s a learnable combination of hyper-attentive observation, statistically common guesses, and the Barnum effect (vague statements that feel personal to almost anyone) — a skill, not a gift.' }
      ],
      expertNotes: [
        'Domestic-abuse advocates teach "grey rocking" (becoming deliberately unresponsive and uninteresting) as a practical way to reduce a manipulator’s payoff from engaging with you, especially when full no-contact isn’t immediately possible.',
        'Therapists specialising in coercive control recommend keeping a private, dated log of incidents — the pattern is often far clearer written down over weeks than it feels in any single moment.',
        'Cult-recovery specialists note that Lifton’s "milieu control" criterion (restricting outside information and relationships) is consistently one of the earliest and most reliable warning signs, appearing well before more overt tactics.',
        'Domestic-abuse and reproductive-health organisations treat reproductive coercion (contraceptive sabotage, pregnancy pressure) as its own named, recognised category of coercive control, distinct from but related to sexual coercion.',
        'Clinicians who work with DARVO note that the "reverse victim and offender" step is usually the most disorienting part precisely because it happens fast, right after a real accountability moment — expecting it in advance makes it far easier to recognise when it starts.',
        'Researchers studying high-control groups distinguish "loaded language" (jargon and in-group phrases that compress complex ideas into simple, hard-to-question slogans) as a separate, later-stage tactic from milieu control — worth learning to spot on its own.',
        'Cognitive-interview trained investigators deliberately ask someone to recall events out of order specifically to raise cognitive load, since a fabricated account is harder to maintain under that pressure than a genuine memory.',
        'Statement analysts treat distancing language, tense shifts and unnecessary qualifiers as prompts for a specific follow-up question, never as proof by themselves — the value is in what the follow-up reveals, not the original phrase.',
        'Emotion researchers trained in Ekman’s FACS method still rely on slow-motion video review for reliable micro-expression detection in practice — real-time accuracy without training aids is far lower than TV depicts.',
        'Professional profilers are trained to distrust their own read of a single gesture and instead look for multiple channels (speech, posture, breathing) shifting together, right after a specific trigger, before treating anything as meaningful.'
      ],
      examples: [{ q: 'A partner insists a conversation you clearly remember never happened. What is this?', working: 'Repeated denial designed to make you doubt your own memory and perception', answer: 'Gaslighting' }, { q: 'Confronted about lying, someone snaps "how dare you accuse me, you’re the one who’s always lying to me." What is this?', working: 'Deny the act, attack the accuser, then reverse who looks like the victim', answer: 'DARVO' }, { q: 'A partner keeps pushing after being told no, until the other person gives in just to end the pressure. What is this?', working: 'Repeated pressure overriding a genuine "no" — no physical force needed for it to count', answer: 'Sexual coercion' }, { q: 'Someone showers a new partner with gifts and constant attention in the first two weeks, then suddenly goes cold for several days with no explanation.', working: 'Fast-tracked intimacy (love bombing) followed by unpredictable withdrawal (intermittent reinforcement) — together, not by coincidence', answer: 'Love bombing + intermittent reinforcement' }, { q: 'A friend group member frequently says things like "real members of this group would never even ask that question."', working: 'Loaded, in-group language used to make questioning the group itself feel like a personal failure', answer: 'Loaded language (thought-reform tactic)' }, { q: 'Someone says "I did not, to the best of my recollection, ever say that" instead of a simple "no, I didn’t."', working: 'Unnecessary hedging in a denial can signal the speaker is protecting themselves from a later contradiction', answer: 'Distancing language / excessive qualifiers (statement analysis)' }, { q: 'A colleague’s speech speeds up, their breathing changes and their posture stiffens all at once, right after one specific question — not before it.', working: 'Multiple channels shifting together, timed to a specific trigger, deviating from their own normal baseline', answer: 'Baseline deviation clustering' }, { q: 'A stranger at a party guesses uncannily personal things about you within a minute of meeting.', working: 'High-resolution observation of small details plus statistically common guesses, often wrapped in vague statements that feel personal to almost anyone', answer: 'Cold reading (combined with the Barnum effect)' }]
    }
  };

  var FORMULAS = [
    { topic: 'Persuasion', name: 'Cialdini\u2019s 6 principles of influence', formula: 'Reciprocity, Commitment/Consistency, Social Proof, Authority, Liking, Scarcity', when: 'Analysing or designing any persuasive request, ad or negotiation.', example: 'A limited-time discount combines scarcity with a implied social-proof "everyone\u2019s buying now".', tip: 'Spotting which principle is being used to persuade you is the first step to resisting it.' },
    { topic: 'Habits', name: 'The habit loop', formula: 'Cue \u2192 Routine \u2192 Reward', when: 'Building a new habit or breaking an old one.', example: 'Phone buzzes (cue) \u2192 check notifications (routine) \u2192 brief novelty hit (reward).', tip: 'To break a habit, keep the cue but change the routine so the same reward is still met differently.' },
    { topic: 'Habits', name: 'Fogg Behavior Model', formula: 'B = MAP (Behaviour happens when Motivation + Ability + a Prompt converge)', when: 'Diagnosing why a desired behaviour isn\u2019t happening.', example: 'Low ability (too hard) can sink a behaviour even with high motivation and a clear prompt.', tip: 'It\u2019s usually easier to raise ability (simplify the task) than to raise motivation.' },
    { topic: 'Motivation', name: 'Self-Determination Theory\u2019s 3 needs', formula: 'Autonomy + Competence + Relatedness', when: 'Explaining why intrinsic motivation is (or isn\u2019t) sustained.', example: 'A job with no autonomy can feel demotivating even with good pay.', tip: 'All three needs matter \u2014 satisfying only one or two leaves motivation fragile.' },
    { topic: 'Motivation', name: 'Goal-Setting Theory', formula: 'Specific + Challenging goals + Feedback + Commitment \u2192 higher performance', when: 'Designing goals for yourself or a team.', example: '"Increase sales 15% by June, reviewed monthly" beats "try to sell more".', tip: 'A hard goal without feedback on progress rarely outperforms an easy one.' },
    { topic: 'Emotion', name: 'Yerkes-Dodson law', formula: 'Performance peaks at MODERATE arousal (inverted U-shape)', when: 'Managing pressure before a performance, exam or event.', example: 'Some nerves sharpen focus; overwhelming panic collapses it.', tip: 'The optimal arousal point shifts lower for very difficult or unfamiliar tasks.' },
    { topic: 'Biases', name: 'Loss aversion ratio', formula: 'Losses are felt roughly ~2\u00d7 as strongly as equivalent gains', when: 'Understanding why people avoid risk even in fair bets.', example: 'Most people reject a 50/50 bet to win $100 or lose $100 \u2014 the possible loss looms larger.', tip: 'Framing a change as "avoiding a loss" is usually more motivating than framing it as "gaining a benefit".' },
    { topic: 'Social Psychology', name: 'Fundamental attribution error', formula: 'Others\u2019 behaviour \u2192 blamed on character | Your own behaviour \u2192 blamed on situation', when: 'Judging why someone (including yourself) acted a certain way.', example: '"She\u2019s rude" (them) vs "I was having a bad day" (you), for the same snapped remark.', tip: 'Deliberately considering situational factors for others reduces unfair judgement.' },
    { topic: 'Habits', name: 'Stages of Change', formula: 'Precontemplation \u2192 Contemplation \u2192 Preparation \u2192 Action \u2192 Maintenance', when: 'Understanding where someone is in a behaviour-change journey.', example: 'Someone who "hasn\u2019t thought about quitting" is at a very different stage than someone already trying patches.', tip: 'Relapse usually means looping back a stage, not starting from zero.' },
    { topic: 'Motivation', name: 'Flow channel', formula: 'Flow occurs when Challenge \u2248 Skill (both reasonably high)', when: 'Designing engaging tasks, games or practice sessions.', example: 'A task far below your skill feels boring; one far above it feels like anxiety, not flow.', tip: 'Gradually raising both challenge and skill together keeps a task in the flow channel as you improve.' },
    { topic: 'Sales', name: 'Framing formula', formula: 'Same fact, reframed: Cost \u2192 Investment | Feature \u2192 Outcome | "Do you want to?" \u2192 "Which do you prefer?"', when: 'Wording a pitch, a price, or a call-to-action.', example: '"What is this costing you in lost time each month?" reframes inaction as a loss, not a neutral non-decision.', tip: 'Framing changes which true fact feels most salient \u2014 it should never be used to state something untrue.' },
    { topic: 'Sales', name: 'Authority positioning checklist', formula: 'Specific result + confident language + third-party validation = perceived authority', when: 'Opening a pitch, writing a bio, or handling "why should I trust you?".', example: '"Helped 47 businesses fix this exact problem last year" beats "I have lots of experience".', tip: 'Vague claims sound like marketing; specific, checkable claims sound like evidence.' },
    { topic: 'Sales', name: 'Objection-reframing formula', formula: 'Feel (validate) \u2192 Felt (normalise) \u2192 Found (evidence) \u2192 narrowing either/or question', when: 'A prospect stalls with a vague objection like "I need to think about it".', example: '"Totally understand \u2014 others felt the same \u2014 here\u2019s what they found. Is it the timing or the price?"', tip: 'Arguing directly against a vague stall rarely works; narrow it to something specific first.' }
  ];

